mapper.insert:
/*
    SQL ID : OrgDAO.orgRegist
    설  명 : 기관 기본정보 등록
*/
INSERT INTO TB_LMS_ORG
(
  ORG_ID
, ORGNM
, ORG_SHRTNM
, ORG_NCNM
, ORG_TYCD
, ZIP_CD
, ADDR1
, ADDR2
, USEYN
, BSC_LANG_CD
, OFC_TELNO
, RPRS_TELNO
, CHRGRNM
, CHRGR_CNTCT
, CHRGR_EML
, CPRGHT_CTS
, HMPG_URL
, RGTR_ID
, REG_DTTM
)
VALUES
(
  #{orgId}
, #{orgnm}
, #{orgShrtnm}
, #{orgNcnm}
, #{orgTycd}
, #{zipCd}
, #{addr1}
, #{addr2}
, #{useyn}
, #{bscLangCd}
, #{ofcTelno}
, #{rprsTelno}
, #{chrgrnm}
, #{chrgrCntct}
, #{chrgrEml}
, #{cprghtCts}
, #{hmpgUrl}
, #{rgtrId}
, FN_DTTM()
)

mapper.update:
/*
    SQL ID : OrgDAO.orgRegist
    설  명 : 기관 기본정보 수정
*/
UPDATE TB_LMS_ORG
SET ORGNM       = #{orgnm}
  , ORG_SHRTNM  = #{orgShrtnm}
  , ORG_TYCD    = #{orgTycd}
  , ZIP_CD      = #{zipCd}
  , ADDR1       = #{addr1}
  , ADDR2       = #{addr2}

  , USEYN       = #{useyn}


  , BSC_LANG_CD = #{bscLangCd}

  , OFC_TELNO   = #{ofcTelno}
  , RPRS_TELNO  = #{rprsTelno}
  , CHRGRNM     = #{chrgrnm}
  , CHRGR_CNTCT = #{chrgrCntct}
  , CHRGR_EML   = #{chrgrEml}
  , CPRGHT_CTS  = #{cprghtCts}
  , HMPG_URL    = #{hmpgUrl}
  , MDFR_ID     = #{mdfrId}
  , MOD_DTTM    = FN_DTTM()
WHERE ORG_ID    = #{orgId}

mapper.delete:
/*
    SQL ID : OrgDAO.orgDelete
    설  명 : 기관 삭제
*/
DELETE FROM TB_LMS_ORG
WHERE ORG_ID = #{orgId}

mapper.select:
/* SQL ID : OrgDAO.orgTmpltListPaging 설 명 : 기관 템플릿 목록 페이징 */
SELECT ROW_NUMBER() OVER(ORDER BY A.ORG_ID DESC) AS LINE_NO , A.* , B.ORGNM , B.ORG_SHRTNM , B.CHRGRNM , B.CHRGR_CNTCT , B.CHRGR_EML , COUNT(*) OVER() AS TOTAL_CNT FROM TB_LMS_ORG_TMPLT A JOIN TB_LMS_ORG B ON A.ORG_ID = B.ORG_ID WHERE 1=1 AND A.USEYN = 'Y'
AND ( LOWER(B.ORG_ID) LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR B.ORGNM LIKE FN_LIKE_VAL(LOWER(#{searchValue})) OR B.CHRGRNM LIKE FN_LIKE_VAL(LOWER(#{searchValue})) )

