SET
  WIDGET_STNG_CTS = #{widgetStngCts}
, MDFR_ID = #{mdfrId}
, MOD_DTTM = FN_DTTM()

, WIDGETNM = #{widgetnm}


, WIDGET_EXPLN = #{widgetExpln}


, WIDGET_VRSN = #{widgetVrsn}


, PVSNYN = #{pvsnyn}

WHERE ORG_ID = #{orgId}
AND WIDGET_USER_GBNCD = #{widgetUserGbncd}

