mapper.update:
/*
    SQL ID : OrgDAO.orgOptnModify
    설  명 : 기관 LMS 옵션 수정
*/
UPDATE TB_LMS_ORG_STNG
SET STNG_VL = #{stngVl}
  , MDFR_ID = #{mdfrId}
  , MOD_DTTM = FN_DTTM()
WHERE ORG_STNG_ID = #{orgStngId}
  AND ORG_ID = #{orgId}
  AND STNG_CD = #{stngCd}

