    SET STNG_VL = #{item.stngVl}
      , MDFR_ID = #{item.mdfrId}
      , MOD_DTTM = FN_DTTM()
    WHERE ORG_STNG_ID = #{item.orgStngId}
      AND ORG_ID = #{item.orgId}
      AND STNG_CD = #{item.stngCd}

