mapper.select:
/*
    SQL ID : OrgDAO.orgAisLinkInfoSelect
    설  명 : 기관 학사연동 정보 단건 조회
*/
SELECT A.*
     , B.CDNM AS AIS_LINK_TYNM
FROM TB_LMS_AIS_LINK A
JOIN TB_LMS_CMMN_CD B ON A.AIS_LINK_TYCD = B.CD
WHERE A.AIS_LINK_TYCD = #{aisLinkTycd}
  AND A.ORG_ID = #{orgId}

